pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based: the first retry doubles the base zero times.
    // Clamp the shift so `base_delay_ms << shift` can never overflow u64
    // (debug panic / release wrap); huge attempts then saturate at the cap.
    let shift = attempt
        .saturating_sub(1)
        .min(63)
        .min(config.base_delay_ms.leading_zeros());
    let raw = config.base_delay_ms << shift;
    if raw > config.max_delay_ms {
        config.max_delay_ms
    } else {
        raw
    }
}

